const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================================\n// schema.prisma — اسکیمای کامل دیتابیس فروشگاه اینترنتی\n// ----------------------------------------------------------------------------\n// نکات کلی:\n// - تمام مقادیر مالی (قیمت، تخفیف، موجودی کیف پول و ...) به صورت Int و در\n//   واحد «تومان» در نظر گرفته شده‌اند. اگر مبالغ بسیار بزرگ (بیش از ۲٫۱ میلیارد)\n//   دارید، این فیلدها را به BigInt تغییر دهید.\n// - شناسه‌ها (id) از نوع cuid() هستند تا هم در سمت کلاینت قابل تولید باشند و هم\n//   ترتیب‌پذیر و یکتا باشند.\n// - برای جلوگیری از وابستگی سخت به یک رکورد در حال تغییر (مثل آدرس یا تنوع\n//   محصول که ممکن است بعداً ویرایش/حذف شود)، در سفارش‌ها از «اسنپ‌شات» داده\n//   (snapshot) استفاده شده تا تاریخچه سفارش هرگز تغییر نکند.\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\" // در صورت نیاز می‌توانید به mysql تغییر دهید\n}\n\n// ============================================================================\n// ENUMS\n// ============================================================================\n\nenum Role {\n  ADMIN\n  EDITOR\n  SUPPORT\n  CUSTOMER\n}\n\nenum ProductStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nenum DiscountType {\n  PERCENT\n  FIXED\n}\n\nenum AttributeInputType {\n  TEXT\n  COLOR\n  SELECT\n}\n\nenum MediaType {\n  IMAGE\n  VIDEO\n  DOCUMENT\n}\n\nenum OtpChannel {\n  SMS\n  EMAIL\n}\n\nenum OtpPurpose {\n  REGISTER\n  LOGIN\n  RESET_PASSWORD\n  VERIFY_PHONE\n  VERIFY_EMAIL\n  CHANGE_PHONE\n}\n\nenum OrderStatus {\n  PENDING_PAYMENT\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n  RETURN_REQUESTED\n  RETURNED\n  REFUNDED\n  FAILED\n}\n\nenum PaymentMethod {\n  GATEWAY\n  WALLET\n  MIXED\n}\n\nenum PaymentStatus {\n  PENDING\n  SUCCESS\n  FAILED\n  REFUNDED\n}\n\nenum TransactionType {\n  ORDER_PAYMENT\n  WALLET_CHARGE\n  REFUND\n}\n\nenum CancellationStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum ReturnStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  RECEIVED\n  REFUNDED\n}\n\nenum WalletTransactionType {\n  DEPOSIT\n  WITHDRAW\n  PURCHASE\n  REFUND\n  ADMIN_ADJUST\n  WITHDRAWAL_REQUEST\n}\n\nenum TicketStatus {\n  OPEN\n  ANSWERED\n  CLOSED\n  PENDING_CUSTOMER\n}\n\nenum TicketPriority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\nenum SenderType {\n  USER\n  ADMIN\n}\n\nenum CommentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// برای کامنت‌های پلی‌مورفیک — قابل اتصال هم به محصول هم به پست وبلاگ\n// (معادل polymorphic relation در Laravel؛ پریزما رابطه‌ی پلی‌مورفیک بومی\n// ندارد، پس با یک ستون نوع + یک ستون شناسه‌ی عمومی شبیه‌سازی می‌شود)\nenum CommentableType {\n  PRODUCT\n  BLOG_POST\n}\n\nenum PostStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nenum NotificationType {\n  ORDER\n  SYSTEM\n  TICKET\n  PROMOTION\n  WALLET\n  COMMENT\n}\n\nenum BannerPosition {\n  HOME_MAIN\n  HOME_MIDDLE\n  CATEGORY_TOP\n  SIDEBAR\n}\n\nenum WalletWithdrawalStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// ============================================================================\n// Users & Authentication\n// ============================================================================\n\nmodel User {\n  id              Int       @id @default(autoincrement())\n  fullName        String?\n  email           String?   @unique\n  phone           String?   @unique\n  password        String?\n  role            Role      @default(CUSTOMER)\n  emailVerifiedAt DateTime?\n  phoneVerifiedAt DateTime?\n\n  isBlocked     Boolean   @default(false)\n  blockedReason String?\n  blockedAt     DateTime?\n  lastLoginAt   DateTime?\n  lastLoginIp   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  addresses          Address[]\n  sessions           UserSession[]\n  otpCodes           OtpCode[]\n  loginAttempts      LoginAttempt[]\n  wallet             Wallet?\n  cart               Cart?\n  wishlists          Wishlist[]\n  orders             Order[]\n  comments           Comment[]\n  commentLikes       CommentLike[]\n  tickets            Ticket[]\n  ticketMessages     TicketMessage[]\n  notifications      Notification[]\n  discountCodeUsers  DiscountCodeUser[]\n  discountCodeUsages DiscountCodeUsage[]\n  transactions       Transaction[]\n  uploadedMedia      Media[]             @relation(\"UploadedMedia\")\n  createdProducts    Product[]           @relation(\"ProductCreatedBy\")\n  blogPosts          BlogPost[]          @relation(\"BlogPostAuthor\")\n  auditLogs          AuditLog[]\n  walletWithdrawals  WalletWithdrawal[]\n\n  @@index([role])\n}\n\nmodel WalletWithdrawal {\n  id          Int                    @id @default(autoincrement())\n  userId      Int\n  user        User                   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  amount      Int\n  status      WalletWithdrawalStatus @default(PENDING)\n  description String?\n  adminNote   String?\n  createdAt   DateTime               @default(now())\n  reviewedAt  DateTime?\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel Address {\n  id            Int      @id @default(autoincrement())\n  userId        Int\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  title         String?\n  receiverName  String\n  receiverPhone String\n  province      String\n  city          String\n  postalCode    String?\n  fullAddress   String\n  lat           Float?\n  lng           Float?\n  isDefault     Boolean  @default(false)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  orders Order[]\n\n  @@index([userId])\n}\n\nmodel UserSession {\n  id             Int       @id @default(autoincrement())\n  userId         Int\n  user           User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token          String    @unique\n  ip             String?\n  userAgent      String?\n  deviceName     String?\n  isActive       Boolean   @default(true)\n  lastActivityAt DateTime  @default(now())\n  createdAt      DateTime  @default(now())\n  expiresAt      DateTime?\n\n  @@index([userId])\n}\n\nmodel LoginAttempt {\n  id           Int      @id @default(autoincrement())\n  userId       Int?\n  user         User?    @relation(fields: [userId], references: [id])\n  identifier   String\n  ip           String?\n  userAgent    String?\n  isSuccessful Boolean  @default(false)\n  createdAt    DateTime @default(now())\n\n  @@index([identifier])\n  @@index([ip])\n}\n\nmodel BlockedIp {\n  id        Int       @id @default(autoincrement())\n  ip        String    @unique\n  reason    String?\n  blockedAt DateTime  @default(now())\n  expiresAt DateTime?\n}\n\nmodel OtpCode {\n  id         Int        @id @default(autoincrement())\n  userId     Int?\n  user       User?      @relation(fields: [userId], references: [id])\n  identifier String\n  channel    OtpChannel\n  purpose    OtpPurpose\n  code       String\n  attempts   Int        @default(0)\n  isUsed     Boolean    @default(false)\n  expiresAt  DateTime\n  createdAt  DateTime   @default(now())\n\n  @@index([identifier, purpose])\n}\n\n// ============================================================================\n// Central Media Model — single source of truth for all uploaded files\n// ============================================================================\n\nmodel Media {\n  id              Int       @id @default(autoincrement())\n  fileName        String // generated unique filename on disk\n  originalName    String // original file name from the user's upload\n  filePath        String // relative path within storage (e.g. \"products/abc.jpg\")\n  url             String // public URL for serving the file\n  mimeType        String\n  extension       String? // file extension extracted from original name (e.g. \"jpg\", \"pdf\", \"mp4\")\n  size            Int // bytes\n  type            MediaType\n  entityType      String? // upload source: \"PRODUCT\", \"BLOG\", \"STORY\", \"BANNER\", etc.\n  storageProvider String    @default(\"local\") // storage backend identifier: \"local\", \"s3\", \"cdn\"\n  uploadedById    Int?\n  uploadedBy      User?     @relation(\"UploadedMedia\", fields: [uploadedById], references: [id])\n  metadata        Json? // flexible metadata (dimensions, duration, alt text, etc.)\n  createdAt       DateTime  @default(now())\n\n  productImages      ProductImage[]\n  categoryImages     Category[]          @relation(\"CategoryImages\")\n  brandLogos         Brand[]             @relation(\"BrandLogos\")\n  shippingLogos      ShippingCompany[]   @relation(\"ShippingLogos\")\n  banners            Banner[]\n  popups             Popup[]\n  ticketAttachments  TicketAttachment[]\n  commentAttachments CommentAttachment[]\n  orderReturnImages  OrderReturnImage[]\n  blogCoverImages    BlogPost[]          @relation(\"BlogCoverImages\")\n  storyCoverImages   Story[]             @relation(\"StoryCoverImages\")\n  storyVideos        Story[]             @relation(\"StoryVideos\")\n\n  @@index([type])\n  @@index([entityType])\n}\n\n// ============================================================================\n// Categories, Brands & Attributes\n// ============================================================================\n\nmodel Category {\n  id              Int        @id @default(autoincrement())\n  name            String\n  slug            String     @unique\n  description     String?\n  // آدرس مستقیم تصویر — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  imageUrl        String?\n  // ارجاع به رکورد Media در کتابخانه متمرکز (برای مدیریت ادمین)\n  imageMediaId    Int?\n  image           Media?     @relation(\"CategoryImages\", fields: [imageMediaId], references: [id])\n  parentId        Int?\n  parent          Category?  @relation(\"CategoryHierarchy\", fields: [parentId], references: [id])\n  children        Category[] @relation(\"CategoryHierarchy\")\n  order           Int        @default(0)\n  isActive        Boolean    @default(true)\n  metaTitle       String?\n  metaDescription String?\n  canonicalUrl    String?\n  createdAt       DateTime   @default(now())\n  updatedAt       DateTime   @updatedAt\n\n  products      ProductCategory[]\n  discountCodes DiscountCodeCategory[]\n  attributes    CategoryAttribute[]\n\n  @@index([parentId])\n}\n\nmodel Brand {\n  id              Int      @id @default(autoincrement())\n  name            String\n  slug            String   @unique\n  description     String?\n  // آدرس مستقیم لوگو — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  logoUrl         String?\n  // ارجاع به رکورد Media در کتابخانه متمرکز (برای مدیریت ادمین)\n  logoMediaId     Int?\n  logo            Media?   @relation(\"BrandLogos\", fields: [logoMediaId], references: [id])\n  isActive        Boolean  @default(true)\n  metaTitle       String?\n  metaDescription String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  products Product[]\n}\n\nmodel Attribute {\n  id           Int                @id @default(autoincrement())\n  name         String\n  slug         String             @unique\n  inputType    AttributeInputType @default(SELECT)\n  isFilterable Boolean            @default(true)\n  isVariant    Boolean            @default(true)\n  isDisplay    Boolean            @default(false)\n  createdAt    DateTime           @default(now())\n\n  values                       AttributeValue[]\n  categories                   CategoryAttribute[]\n  productDisplayAttributeValue ProductDisplayAttributeValue[]\n}\n\nmodel AttributeValue {\n  id          Int       @id @default(autoincrement())\n  attributeId Int\n  attribute   Attribute @relation(fields: [attributeId], references: [id], onDelete: Cascade)\n  value       String\n  colorHex    String?\n  order       Int       @default(0)\n\n  variantValues ProductVariantAttributeValue[]\n\n  @@unique([attributeId, value])\n}\n\n// تعیین می‌کند کدام ویژگی‌ها برای کدام دسته‌بندی معنی دارند (مثلا «سایز کفش» فقط در دسته کفش)\nmodel CategoryAttribute {\n  id          Int       @id @default(autoincrement())\n  categoryId  Int\n  category    Category  @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  attributeId Int\n  attribute   Attribute @relation(fields: [attributeId], references: [id], onDelete: Cascade)\n\n  @@unique([categoryId, attributeId])\n}\n\n// ============================================================================\n// Products & Variants\n// ============================================================================\n\nmodel Product {\n  id               Int           @id @default(autoincrement())\n  name             String\n  slug             String        @unique\n  brandId          Int?\n  brand            Brand?        @relation(fields: [brandId], references: [id])\n  shortDescription String?\n  description      String?\n  status           ProductStatus @default(DRAFT)\n  isFeatured       Boolean       @default(false)\n  viewCount        Int           @default(0)\n\n  basePrice Int @default(0)\n\n  discountType      DiscountType?\n  discountValue     Int?\n  // فیلدهای denormalize شده — هر بار که تنوع‌های محصول (variants) تغییر\n  // می‌کند (ایجاد/ویرایش/حذف)، این مقادیر در سرویس مربوطه بازمحاسبه و\n  // به‌روزرسانی می‌شوند. دلیل: مرتب‌سازی/فیلتر بر اساس قیمت یا موجودی\n  // مستقیماً روی محصولات بسیار سریع‌تر و مطمئن‌تر از join زنده با variants\n  // در هر کوئری لیست محصولات صفحه فروشگاه است.\n  minPrice          Int           @default(0) // کمترین قیمت بین تنوع‌های فعال\n  maxPrice          Int           @default(0) // بیشترین قیمت بین تنوع‌های فعال\n  isInStock         Boolean       @default(false) // آیا حداقل یک تنوع فعال موجودی دارد\n  hasActiveDiscount Boolean       @default(false) // آیا حداقل یک تنوع تخفیف فعال دارد\n  avgRating         Float         @default(0) // میانگین امتیاز کاربران (از کامنت‌های APPROVED با rating)\n  reviewCount       Int           @default(0) // تعداد کامنت‌های APPROVED دارای امتیاز\n  totalSold         Int           @default(0) // تعداد کل فروش (از سفارش‌های تحویل‌شده)\n\n  metaTitle       String?\n  metaDescription String?\n  canonicalUrl    String?\n  structuredData  Json? // override دستی برای Schema.org در صورت نیاز\n\n  createdById Int?\n  createdBy   User?    @relation(\"ProductCreatedBy\", fields: [createdById], references: [id])\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  categories             ProductCategory[]\n  variants               ProductVariant[]\n  images                 ProductImage[]\n  wishlists              Wishlist[]\n  discountCodes          DiscountCodeProduct[]\n  displayAttributeValues ProductDisplayAttributeValue[]\n  stories                StoryProduct[]\n  blogPosts              BlogPostProduct[]\n\n  @@index([brandId])\n  @@index([status])\n  @@index([isFeatured])\n  @@index([basePrice])\n  @@index([isInStock])\n}\n\n// محصول می‌تواند در چند دسته‌بندی همزمان قرار بگیرد\nmodel ProductCategory {\n  id         Int      @id @default(autoincrement())\n  productId  Int\n  product    Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  categoryId Int\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([productId, categoryId])\n}\n\nmodel ProductImage {\n  id        Int     @id @default(autoincrement())\n  productId Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  mediaId   Int\n  media     Media   @relation(fields: [mediaId], references: [id])\n  order     Int     @default(0)\n  isMain    Boolean @default(false)\n\n  @@index([productId])\n}\n\nmodel ProductVariant {\n  id        Int     @id @default(autoincrement())\n  productId Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  sku       String  @unique\n\n  priceAdjustment Int     @default(0)\n  stock           Int     @default(0)\n  weight          Float?\n  isDefault       Boolean @default(false)\n  isActive        Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  attributeValues ProductVariantAttributeValue[]\n  cartItems       CartItem[]\n  orderItems      OrderItem[]\n\n  @@index([productId])\n}\n\nmodel ProductVariantAttributeValue {\n  id               Int            @id @default(autoincrement())\n  variantId        Int\n  variant          ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n  attributeValueId Int\n  attributeValue   AttributeValue @relation(fields: [attributeValueId], references: [id], onDelete: Cascade)\n\n  @@unique([variantId, attributeValueId])\n}\n\nmodel ProductDisplayAttributeValue {\n  id          Int       @id @default(autoincrement())\n  productId   Int\n  product     Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  attributeId Int\n  attribute   Attribute @relation(fields: [attributeId], references: [id])\n  value       String\n\n  @@unique([productId, attributeId])\n}\n\n// ============================================================================\n// Wishlist & Comparison\n// ============================================================================\n\nmodel Wishlist {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  productId Int\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([userId, productId])\n}\n\n// ============================================================================\n// Cart\n// ============================================================================\n\nmodel Cart {\n  id         Int      @id @default(autoincrement())\n  userId     Int?     @unique\n  user       User?    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  guestToken String?  @unique\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  items CartItem[]\n\n  @@index([guestToken])\n}\n\nmodel CartItem {\n  id        Int            @id @default(autoincrement())\n  cartId    Int\n  cart      Cart           @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  variantId Int\n  variant   ProductVariant @relation(fields: [variantId], references: [id])\n  quantity  Int            @default(1)\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@unique([cartId, variantId])\n}\n\n// ============================================================================\n// Discount Codes\n// ============================================================================\n\nmodel DiscountCode {\n  id                Int          @id @default(autoincrement())\n  code              String       @unique\n  type              DiscountType\n  value             Int // درصد یا مبلغ ثابت بسته به type\n  maxDiscountAmount Int? // سقف تخفیف برای نوع درصدی\n  minCartAmount     Int? // حداقل مبلغ سبد خرید برای فعال‌شدن کد\n\n  maxUsage        Int? // حداکثر تعداد استفاده کلی از کد\n  maxUsagePerUser Int? // حداکثر تعداد استفاده هر کاربر از کد\n  usageCount      Int  @default(0) // شمارنده کل استفاده‌ها (برای سرعت بیشتر)\n\n  startsAt  DateTime? // محدودیت زمانی فعال بودن کد\n  expiresAt DateTime?\n  isActive  Boolean   @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // در صورت خالی بودن این روابط، یعنی محدودیتی روی محصول/دسته/کاربر وجود ندارد\n  products   DiscountCodeProduct[]\n  categories DiscountCodeCategory[]\n  users      DiscountCodeUser[]\n  usages     DiscountCodeUsage[]\n  orders     Order[]\n}\n\n// کد تخفیف مخصوص چند محصول خاص\nmodel DiscountCodeProduct {\n  id             Int          @id @default(autoincrement())\n  discountCodeId Int\n  discountCode   DiscountCode @relation(fields: [discountCodeId], references: [id], onDelete: Cascade)\n  productId      Int\n  product        Product      @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([discountCodeId, productId])\n}\n\n// کد تخفیف مخصوص چند دسته‌بندی خاص\nmodel DiscountCodeCategory {\n  id             Int          @id @default(autoincrement())\n  discountCodeId Int\n  discountCode   DiscountCode @relation(fields: [discountCodeId], references: [id], onDelete: Cascade)\n  categoryId     Int\n  category       Category     @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n\n  @@unique([discountCodeId, categoryId])\n}\n\n// کد تخفیف مخصوص چند کاربر خاص\nmodel DiscountCodeUser {\n  id             Int          @id @default(autoincrement())\n  discountCodeId Int\n  discountCode   DiscountCode @relation(fields: [discountCodeId], references: [id], onDelete: Cascade)\n  userId         Int\n  user           User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([discountCodeId, userId])\n}\n\n// تاریخچه واقعی استفاده از کد تخفیف — مبنای محاسبه maxUsage و maxUsagePerUser\nmodel DiscountCodeUsage {\n  id             Int          @id @default(autoincrement())\n  discountCodeId Int\n  discountCode   DiscountCode @relation(fields: [discountCodeId], references: [id], onDelete: Cascade)\n  userId         Int\n  user           User         @relation(fields: [userId], references: [id])\n  orderId        Int          @unique\n  order          Order        @relation(fields: [orderId], references: [id])\n  discountAmount Int\n  usedAt         DateTime     @default(now())\n\n  @@index([discountCodeId, userId])\n}\n\n// ============================================================================\n// Shipping\n// ============================================================================\n\nmodel ShippingCompany {\n  id               Int     @id @default(autoincrement())\n  name             String\n  // آدرس مستقیم لوگو — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  logoUrl          String?\n  // ارجاع به رکورد Media در کتابخانه متمرکز (برای مدیریت ادمین)\n  logoMediaId      Int?\n  logo             Media?  @relation(\"ShippingLogos\", fields: [logoMediaId], references: [id])\n  description      String?\n  baseCost         Int     @default(0)\n  estimatedDaysMin Int?\n  estimatedDaysMax Int?\n  isActive         Boolean @default(true)\n\n  orders Order[]\n}\n\n// ============================================================================\n// Payment & Transactions\n// ============================================================================\n\nmodel PaymentGateway {\n  id       Int     @id @default(autoincrement())\n  name     String\n  slug     String  @unique\n  isActive Boolean @default(true)\n  config   Json? // merchantId و سایر تنظیمات اتصال به درگاه\n\n  transactions Transaction[]\n}\n\n// هر تراکنش پولی: پرداخت سفارش از درگاه، شارژ کیف پول یا بازگشت وجه\nmodel Transaction {\n  id           Int             @id @default(autoincrement())\n  orderId      Int?\n  order        Order?          @relation(fields: [orderId], references: [id])\n  gatewayId    Int?\n  gateway      PaymentGateway? @relation(fields: [gatewayId], references: [id])\n  userId       Int\n  user         User            @relation(fields: [userId], references: [id])\n  type         TransactionType\n  amount       Int\n  status       PaymentStatus   @default(PENDING)\n  refId        String? // شماره مرجع درگاه\n  trackingCode String?         @unique\n  createdAt    DateTime        @default(now())\n\n  @@index([orderId])\n  @@index([userId])\n}\n\n// ============================================================================\n// Orders\n// ============================================================================\n\nmodel Order {\n  id          Int    @id @default(autoincrement())\n  orderNumber String @unique\n  userId      Int\n  user        User   @relation(fields: [userId], references: [id])\n\n  // آدرس به صورت اسنپ‌شات ذخیره می‌شود تا حتی با تغییر/حذف آدرس اصلی،\n  // سفارش‌های قبلی دست‌نخورده بمانند\n  addressId       Int?\n  address         Address? @relation(fields: [addressId], references: [id])\n  shippingAddress Json? // کپی کامل آدرس در لحظه ثبت سفارش (حتی اگر آدرس اصلی بعداً تغییر/حذف شود)\n\n  shippingCompanyId Int?\n  shippingCompany   ShippingCompany? @relation(fields: [shippingCompanyId], references: [id])\n  shippingCost      Int              @default(0)\n  trackingCode      String?\n  packageNumber     String?\n\n  subtotal       Int // جمع کل قبل از تخفیف و هزینه ارسال\n  discountAmount Int @default(0)\n  taxAmount      Int @default(0)\n  totalAmount    Int\n\n  discountCodeId Int?\n  discountCode   DiscountCode? @relation(fields: [discountCodeId], references: [id])\n\n  paymentMethod PaymentMethod @default(GATEWAY)\n  status        OrderStatus   @default(PENDING_PAYMENT)\n  paidAt        DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  items              OrderItem[]\n  transactions       Transaction[]\n  statusHistory      OrderStatusHistory[]\n  cancellation       OrderCancellation?\n  returns            OrderReturn[]\n  discountUsage      DiscountCodeUsage?\n  tickets            Ticket[]\n  walletTransactions WalletTransaction[]\n\n  @@index([userId])\n  @@index([status])\n}\n\nmodel OrderItem {\n  id        Int            @id @default(autoincrement())\n  orderId   Int\n  order     Order          @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  variantId Int\n  variant   ProductVariant @relation(fields: [variantId], references: [id])\n\n  // اسنپ‌شات اطلاعات کالا در لحظه خرید (مستقل از تغییرات بعدی محصول)\n  productName       String\n  variantAttributes String? // خلاصه‌ای مثل «قرمز - سایز L»\n  price             Int // قیمت واحد در لحظه خرید\n  quantity          Int\n  discountAmount    Int     @default(0)\n\n  returns OrderReturn[]\n\n  @@index([orderId])\n}\n\nmodel OrderStatusHistory {\n  id        Int         @id @default(autoincrement())\n  orderId   Int\n  order     Order       @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  status    OrderStatus\n  note      String?\n  createdAt DateTime    @default(now())\n}\n\nmodel OrderCancellation {\n  id          Int                @id @default(autoincrement())\n  orderId     Int                @unique\n  order       Order              @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  reason      String\n  status      CancellationStatus @default(PENDING)\n  requestedAt DateTime           @default(now())\n  reviewedAt  DateTime?\n  adminNote   String?\n}\n\nmodel OrderReturn {\n  id           Int          @id @default(autoincrement())\n  orderId      Int\n  order        Order        @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  orderItemId  Int?\n  orderItem    OrderItem?   @relation(fields: [orderItemId], references: [id])\n  reason       String\n  status       ReturnStatus @default(PENDING)\n  refundAmount Int?\n  createdAt    DateTime     @default(now())\n  reviewedAt   DateTime?\n  adminNote    String?\n\n  images OrderReturnImage[]\n}\n\nmodel OrderReturnImage {\n  id       Int         @id @default(autoincrement())\n  returnId Int\n  return   OrderReturn @relation(fields: [returnId], references: [id], onDelete: Cascade)\n  mediaId  Int\n  media    Media       @relation(fields: [mediaId], references: [id])\n}\n\n// ============================================================================\n// Wallet\n// ============================================================================\n\nmodel Wallet {\n  id        Int      @id @default(autoincrement())\n  userId    Int      @unique\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  balance   Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  transactions WalletTransaction[]\n}\n\nmodel WalletTransaction {\n  id          Int                   @id @default(autoincrement())\n  walletId    Int\n  wallet      Wallet                @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  type        WalletTransactionType\n  amount      Int\n  description String?\n  orderId     Int?\n  order       Order?                @relation(fields: [orderId], references: [id])\n  createdAt   DateTime              @default(now())\n\n  @@index([walletId])\n}\n\n// ============================================================================\n// Tickets\n// ============================================================================\n\nmodel TicketDepartment {\n  id   Int    @id @default(autoincrement())\n  name String\n\n  tickets Ticket[]\n}\n\nmodel Ticket {\n  id           Int               @id @default(autoincrement())\n  userId       Int\n  user         User              @relation(fields: [userId], references: [id])\n  departmentId Int?\n  department   TicketDepartment? @relation(fields: [departmentId], references: [id])\n  subject      String\n  priority     TicketPriority    @default(NORMAL)\n  status       TicketStatus      @default(OPEN)\n  orderId      Int?\n  order        Order?            @relation(fields: [orderId], references: [id])\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n\n  messages TicketMessage[]\n}\n\nmodel TicketMessage {\n  id         Int        @id @default(autoincrement())\n  ticketId   Int\n  ticket     Ticket     @relation(fields: [ticketId], references: [id], onDelete: Cascade)\n  senderId   Int\n  sender     User       @relation(fields: [senderId], references: [id])\n  senderType SenderType\n  message    String\n  createdAt  DateTime   @default(now())\n\n  attachments TicketAttachment[]\n}\n\nmodel TicketAttachment {\n  id        Int           @id @default(autoincrement())\n  messageId Int\n  message   TicketMessage @relation(fields: [messageId], references: [id], onDelete: Cascade)\n  mediaId   Int\n  media     Media         @relation(fields: [mediaId], references: [id])\n}\n\n// ============================================================================\n// Comments\n// ============================================================================\n\nmodel Comment {\n  id              Int             @id @default(autoincrement())\n  // پلی‌مورفیک: به‌جای productId مستقیم، نوع + شناسه‌ی موجودیت مرتبط\n  // (چون Comment الان هم زیر محصول هم زیر پست وبلاگ استفاده می‌شود)\n  commentableType CommentableType\n  commentableId   Int\n  userId          Int\n  user            User            @relation(fields: [userId], references: [id])\n  parentId        Int?\n  parent          Comment?        @relation(\"CommentReplies\", fields: [parentId], references: [id])\n  replies         Comment[]       @relation(\"CommentReplies\")\n  content         String\n  rating          Int? // امتیاز فقط روی کامنت‌های اصلی محصول (سطح اول) معنا دارد\n  status          CommentStatus   @default(PENDING)\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n\n  likes       CommentLike[]\n  attachments CommentAttachment[]\n\n  @@index([commentableType, commentableId])\n  @@index([parentId])\n}\n\nmodel CommentLike {\n  id        Int      @id @default(autoincrement())\n  commentId Int\n  comment   Comment  @relation(fields: [commentId], references: [id], onDelete: Cascade)\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  createdAt DateTime @default(now())\n\n  @@unique([commentId, userId])\n}\n\nmodel CommentAttachment {\n  id        Int     @id @default(autoincrement())\n  commentId Int\n  comment   Comment @relation(fields: [commentId], references: [id], onDelete: Cascade)\n  mediaId   Int\n  media     Media   @relation(fields: [mediaId], references: [id])\n}\n\n// ============================================================================\n// Blog\n// ============================================================================\n\nmodel BlogCategory {\n  id          Int      @id @default(autoincrement())\n  name        String\n  slug        String   @unique\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  posts BlogPost[]\n}\n\nmodel BlogPost {\n  id        Int        @id @default(autoincrement())\n  title     String\n  slug      String     @unique\n  excerpt   String?\n  content   String\n  status    PostStatus @default(DRAFT)\n  viewCount Int        @default(0)\n\n  // آدرس مستقیم تصویر کاور — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  coverImageUrl     String?\n  coverImageMediaId Int?\n  coverImage        Media?  @relation(\"BlogCoverImages\", fields: [coverImageMediaId], references: [id])\n\n  authorId Int?\n  author   User? @relation(\"BlogPostAuthor\", fields: [authorId], references: [id])\n\n  categoryId Int?\n  category   BlogCategory? @relation(fields: [categoryId], references: [id])\n\n  metaTitle       String?\n  metaDescription String?\n  canonicalUrl    String?\n\n  publishedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  products BlogPostProduct[]\n\n  @@index([status])\n  @@index([categoryId])\n}\n\nmodel BlogPostProduct {\n  id         Int      @id @default(autoincrement())\n  blogPostId Int\n  blogPost   BlogPost @relation(fields: [blogPostId], references: [id], onDelete: Cascade)\n  productId  Int\n  product    Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([blogPostId, productId])\n}\n\n// ============================================================================\n// Stories\n// ============================================================================\n\nmodel Story {\n  id                Int      @id @default(autoincrement())\n  title             String\n  // آدرس مستقیم تصویر کاور — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  coverImageUrl     String?\n  coverImageMediaId Int?\n  coverImage        Media?   @relation(\"StoryCoverImages\", fields: [coverImageMediaId], references: [id])\n  // آدرس مستقیم ویدئو — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  videoUrl          String?\n  videoMediaId      Int?\n  video             Media?   @relation(\"StoryVideos\", fields: [videoMediaId], references: [id])\n  expiresAt         DateTime\n  order             Int      @default(0)\n  isActive          Boolean  @default(true)\n  createdAt         DateTime @default(now())\n\n  products StoryProduct[]\n}\n\nmodel StoryProduct {\n  id        Int     @id @default(autoincrement())\n  storyId   Int\n  story     Story   @relation(fields: [storyId], references: [id], onDelete: Cascade)\n  productId Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([storyId, productId])\n}\n\n// ============================================================================\n// Newsletter\n// ============================================================================\n\nmodel Newsletter {\n  id        Int      @id @default(autoincrement())\n  email     String   @unique\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n}\n\n// ============================================================================\n// Notifications\n// ============================================================================\n\nmodel Notification {\n  id        Int              @id @default(autoincrement())\n  userId    Int\n  user      User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  type      NotificationType\n  title     String\n  message   String\n  link      String?\n  isRead    Boolean          @default(false)\n  createdAt DateTime         @default(now())\n\n  @@index([userId, isRead])\n}\n\nmodel AdminNotification {\n  id        Int              @id @default(autoincrement())\n  type      NotificationType\n  title     String\n  message   String\n  link      String?\n  isRead    Boolean          @default(false)\n  createdAt DateTime         @default(now())\n\n  @@index([isRead])\n}\n\n// ============================================================================\n// Banners & Popups\n// ============================================================================\n\nmodel Banner {\n  id       Int            @id @default(autoincrement())\n  title    String?\n  // آدرس مستقیم فایل — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  imageUrl String?\n  // ارجاع به رکورد Media در کتابخانه متمرکز (برای مدیریت ادمین)\n  mediaId  Int?\n  media    Media?         @relation(fields: [mediaId], references: [id])\n  link     String?\n  position BannerPosition\n  order    Int            @default(0)\n  isActive Boolean        @default(true)\n  startsAt DateTime?\n  endsAt   DateTime?\n}\n\nmodel Popup {\n  id                 Int       @id @default(autoincrement())\n  title              String\n  content            String?\n  // آدرس مستقیم فایل — فرانت‌اند برای نمایش از این فیلد استفاده می‌کند\n  mediaUrl           String?\n  // ارجاع به رکورد Media در کتابخانه متمرکز (برای مدیریت ادمین)\n  mediaId            Int?\n  media              Media?    @relation(fields: [mediaId], references: [id])\n  link               String?\n  isActive           Boolean   @default(true)\n  startsAt           DateTime?\n  endsAt             DateTime?\n  showOncePerSession Boolean   @default(true)\n}\n\n// ============================================================================\n// Settings & Audit\n// ============================================================================\n\n// تنظیمات کلید-مقدار قابل تغییر از پنل ادمین (نام فروشگاه، سئوی پیش‌فرض، شبکه‌های اجتماعی و ...)\nmodel Setting {\n  id        Int      @id @default(autoincrement())\n  key       String   @unique\n  value     String\n  type      String   @default(\"string\") // string | number | boolean | json\n  updatedAt DateTime @updatedAt\n}\n\n// لاگ فعالیت‌های مهم — مبنای گزارش‌های امنیتی و برخی نمودارهای آنالیزی\nmodel AuditLog {\n  id        Int      @id @default(autoincrement())\n  userId    Int?\n  user      User?    @relation(fields: [userId], references: [id])\n  action    String\n  entity    String?\n  entityId  String?\n  ip        String?\n  metadata  Json?\n  createdAt DateTime @default(now())\n\n  @@index([entity, entityId])\n}\n"
}

